changeSet.sql:
INSERT INTO clinlims.container_type (id, code, name, category, additive, nominal_volume, volume_unit, cap_colour_hex, cap_colour_name, is_active, edited, last_updated)
 SELECT nextval('clinlims.container_type_seq'), 'K2EDTA4', 'K2EDTA tube 4 mL', 'Blood', 'K2EDTA', 4, 'mL', '#B57EDC', 'Lavender', true, false, now()
 WHERE NOT EXISTS (SELECT 1 FROM clinlims.container_type WHERE code = 'K2EDTA4');
INSERT INTO clinlims.container_type_domain (container_type_id, domain)
 SELECT ct.id, 'CLINICAL' FROM clinlims.container_type ct WHERE ct.code = 'K2EDTA4' AND ct.edited = false
 AND NOT EXISTS (SELECT 1 FROM clinlims.container_type_domain d WHERE d.container_type_id = ct.id AND d.domain = 'CLINICAL');
